create extension if not exists pgcrypto;

create type public.transaction_kind as enum ('buy','sell','dividend','jcp','amortization','split','reverse_split','bonus','custody_transfer','cash_deposit','cash_withdrawal','fee','reconciliation_adjustment');
create type public.job_status as enum ('pending','running','completed','failed');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.brokers (id uuid primary key default gen_random_uuid(), name text not null unique, created_at timestamptz not null default now());
create table public.portfolios (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), name text not null, base_currency text not null default 'BRL', archived_at timestamptz, created_at timestamptz not null default now(), unique(user_id,name));
create table public.investment_accounts (id uuid primary key default gen_random_uuid(), portfolio_id uuid not null references public.portfolios(id), broker_id uuid references public.brokers(id), user_id uuid not null references auth.users(id), name text not null, created_at timestamptz not null default now());
create table public.assets (id uuid primary key default gen_random_uuid(), ticker text not null, isin text, official_name text not null, asset_class text not null, exchange text not null default 'B3', currency text not null default 'BRL', sector text, trading_status text not null default 'active', source text, updated_at timestamptz not null default now(), unique(exchange,ticker));
create table public.transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), portfolio_id uuid not null references public.portfolios(id), account_id uuid references public.investment_accounts(id), asset_id uuid references public.assets(id), kind public.transaction_kind not null, trade_date date not null, settlement_date date, quantity numeric(20,8), unit_price numeric(20,8), gross_amount numeric(20,8), taxes numeric(20,8) not null default 0 check(taxes >= 0), net_amount numeric(20,8), brokerage_note_number text, source text not null default 'manual', source_reference text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), voided_at timestamptz, check ((kind in ('buy','sell') and asset_id is not null and quantity > 0 and unit_price >= 0) or kind not in ('buy','sell')));
create table public.transaction_fees (id uuid primary key default gen_random_uuid(), transaction_id uuid not null references public.transactions(id), description text not null, amount numeric(20,8) not null check(amount >= 0));
create table public.cash_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), portfolio_id uuid not null references public.portfolios(id), transaction_id uuid references public.transactions(id), occurred_on date not null, amount numeric(20,8) not null, category text not null, created_at timestamptz not null default now());
create table public.corporate_actions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), portfolio_id uuid not null references public.portfolios(id), asset_id uuid not null references public.assets(id), action_type text not null, effective_date date not null, ratio_numerator numeric(20,8), ratio_denominator numeric(20,8), source text not null, created_at timestamptz not null default now());
create table public.portfolio_positions (id uuid primary key default gen_random_uuid(), portfolio_id uuid not null references public.portfolios(id), asset_id uuid not null references public.assets(id), as_of_date date not null, quantity numeric(20,8) not null, average_cost numeric(20,8) not null, cost_basis numeric(20,8) not null, realized_profit numeric(20,8) not null default 0, recalculated_at timestamptz not null default now(), unique(portfolio_id,asset_id,as_of_date));
create table public.portfolio_snapshots (id uuid primary key default gen_random_uuid(), portfolio_id uuid not null references public.portfolios(id), reference_date date not null, market_value numeric(20,8), cost_basis numeric(20,8), cash_balance numeric(20,8), created_at timestamptz not null default now(), unique(portfolio_id,reference_date));
create table public.market_prices (id uuid primary key default gen_random_uuid(), asset_id uuid not null references public.assets(id), reference_at timestamptz not null, captured_at timestamptz not null default now(), price numeric(20,8) not null check(price >= 0), currency text not null, source text not null, price_type text not null, delayed boolean not null default true, status text not null default 'available', unique(asset_id,reference_at,source,price_type));
create table public.fundamental_metrics (id uuid primary key default gen_random_uuid(), asset_id uuid not null references public.assets(id), metric_key text not null, value numeric(24,10), reference_date date, captured_at timestamptz not null default now(), source text not null, unique(asset_id,metric_key,reference_date,source));
create table public.asset_analyses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), asset_id uuid references public.assets(id), analysis_type text not null, status text not null, objective_score numeric(8,3), payload jsonb not null, model_version text, prompt_version text not null, market_data_timestamp timestamptz, generated_at timestamptz not null default now());
create table public.news_items (id uuid primary key default gen_random_uuid(), canonical_url text not null unique, title text not null, source text not null, published_at timestamptz, event_at timestamptz, summary text, category text, created_at timestamptz not null default now());
create table public.news_asset_relations (news_item_id uuid references public.news_items(id) on delete cascade, asset_id uuid references public.assets(id) on delete cascade, relevance numeric(5,2), primary key(news_item_id,asset_id));
create table public.watchlists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), name text not null, created_at timestamptz not null default now(), unique(user_id,name));
create table public.watchlist_assets (watchlist_id uuid references public.watchlists(id) on delete cascade, asset_id uuid references public.assets(id), primary key(watchlist_id,asset_id));
create table public.alerts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), asset_id uuid references public.assets(id), rule jsonb not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.alert_events (id uuid primary key default gen_random_uuid(), alert_id uuid not null references public.alerts(id) on delete cascade, occurred_at timestamptz not null default now(), payload jsonb not null, read_at timestamptz);
create table public.import_batches (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), portfolio_id uuid references public.portfolios(id), file_name text not null, document_hash text not null, status text not null default 'uploaded', source text not null default 'xp', created_at timestamptz not null default now(), confirmed_at timestamptz, unique(user_id,document_hash));
create table public.import_records (id uuid primary key default gen_random_uuid(), import_batch_id uuid not null references public.import_batches(id), row_number integer, raw_payload jsonb not null, normalized_payload jsonb, status text not null default 'pending', transaction_id uuid references public.transactions(id), error_message text);
create table public.scheduled_jobs (id uuid primary key default gen_random_uuid(), job_type text not null, status public.job_status not null default 'pending', execution_key text not null unique, started_at timestamptz, finished_at timestamptz, processed_count integer not null default 0, error_message text, attempts integer not null default 0, created_at timestamptz not null default now());
create table public.ai_usage (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), analysis_id uuid references public.asset_analyses(id), model text not null, input_tokens integer, output_tokens integer, estimated_cost_usd numeric(12,6), created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), entity_type text not null, entity_id uuid, action text not null, before_state jsonb, after_state jsonb, created_at timestamptz not null default now());
create table public.app_settings (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), setting_key text not null, value jsonb not null, updated_at timestamptz not null default now(), unique(user_id,setting_key));

create index transactions_user_portfolio_date_idx on public.transactions(user_id, portfolio_id, trade_date);
create index market_prices_asset_reference_idx on public.market_prices(asset_id, reference_at desc);
create index asset_analyses_user_asset_idx on public.asset_analyses(user_id, asset_id, generated_at desc);

alter table public.profiles enable row level security;
alter table public.portfolios enable row level security;
alter table public.investment_accounts enable row level security;
alter table public.transactions enable row level security;
alter table public.transaction_fees enable row level security;
alter table public.cash_entries enable row level security;
alter table public.corporate_actions enable row level security;
alter table public.portfolio_positions enable row level security;
alter table public.portfolio_snapshots enable row level security;
alter table public.asset_analyses enable row level security;
alter table public.watchlists enable row level security;
alter table public.watchlist_assets enable row level security;
alter table public.alerts enable row level security;
alter table public.alert_events enable row level security;
alter table public.import_batches enable row level security;
alter table public.import_records enable row level security;
alter table public.ai_usage enable row level security;
alter table public.audit_logs enable row level security;
alter table public.app_settings enable row level security;

create policy "profile owner" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "portfolio owner" on public.portfolios for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "account owner" on public.investment_accounts for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "transaction owner" on public.transactions for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "transaction fees via owner" on public.transaction_fees for all using (exists(select 1 from public.transactions t where t.id = transaction_id and t.user_id = auth.uid())) with check (exists(select 1 from public.transactions t where t.id = transaction_id and t.user_id = auth.uid()));
create policy "cash owner" on public.cash_entries for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "corporate actions owner" on public.corporate_actions for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "positions via portfolio owner" on public.portfolio_positions for select using (exists(select 1 from public.portfolios p where p.id = portfolio_id and p.user_id = auth.uid()));
create policy "snapshots via portfolio owner" on public.portfolio_snapshots for select using (exists(select 1 from public.portfolios p where p.id = portfolio_id and p.user_id = auth.uid()));
create policy "analysis owner" on public.asset_analyses for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "watchlist owner" on public.watchlists for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "watchlist assets via owner" on public.watchlist_assets for all using (exists(select 1 from public.watchlists w where w.id = watchlist_id and w.user_id = auth.uid())) with check (exists(select 1 from public.watchlists w where w.id = watchlist_id and w.user_id = auth.uid()));
create policy "alert owner" on public.alerts for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "alert events via owner" on public.alert_events for select using (exists(select 1 from public.alerts a where a.id = alert_id and a.user_id = auth.uid()));
create policy "import owner" on public.import_batches for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "import records via owner" on public.import_records for all using (exists(select 1 from public.import_batches b where b.id = import_batch_id and b.user_id = auth.uid())) with check (exists(select 1 from public.import_batches b where b.id = import_batch_id and b.user_id = auth.uid()));
create policy "ai usage owner" on public.ai_usage for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "audit log owner" on public.audit_logs for select using (user_id = auth.uid());
create policy "settings owner" on public.app_settings for all using (user_id = auth.uid()) with check (user_id = auth.uid());
